-- TW MasterData_RegionTw_Production SHA-256: 730d2aea3e7138d0212b64d80d7fe13e2c72ff03086944f3c8d2e325b4b592cc
-- Add garden storage and static configuration; preserve existing player saves.
CREATE TABLE public.player_gardens (
    player_id TEXT PRIMARY KEY REFERENCES public.players(player_id) ON DELETE CASCADE,
    holding_worker_count INTEGER NOT NULL DEFAULT 0 CHECK (holding_worker_count >= 0),
    checked_at BIGINT NOT NULL CHECK (checked_at >= 0)
);
CREATE TABLE public.player_garden_buildings (
    player_id TEXT NOT NULL REFERENCES public.player_gardens(player_id) ON DELETE CASCADE,
    building_code BIGINT NOT NULL,
    level INTEGER NOT NULL CHECK (level >= 0),
    worker_count INTEGER NOT NULL DEFAULT 0 CHECK (worker_count >= 0),
    received_at BIGINT,
    lottery_checked_at BIGINT,
    room_unlocked BOOLEAN NOT NULL DEFAULT FALSE,
    search_inventory_type INTEGER NOT NULL DEFAULT 2,
    search_inventory_code BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (player_id,building_code)
);
CREATE TABLE public.player_room_situations (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    room_code BIGINT NOT NULL,
    situation_code BIGINT NOT NULL,
    played_at BIGINT NOT NULL,
    PRIMARY KEY (player_id,room_code,situation_code)
);
